export default function UpdatePasswordPage() {
  const router = useRouter();
  const supabase = useMemo(() => { try { return createClient(); } catch { return null; } }, []);
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!supabase) return;
    setBusy(true); setMessage(null);
    const { error } = await supabase.auth.updateUser({ password });
    if (error) {
      setMessage(error.message);
      setBusy(false);
      return;
    }
    const upgrade = new URL(window.location.href).searchParams.get("upgrade") === "1";
    if (upgrade) {
      // The auth callback normally claims this already. Repeating the claim is intentionally
      // idempotent so an email-link variant that returns directly here cannot miss the grant.
      await fetch("/api/auth/claim-signup-promo", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).catch(() => undefined);
    }
    setMessage(upgrade ? "Guest account upgraded. Password saved; your existing credits and history remain attached." : "Password updated. Redirecting to your account…");
    setTimeout(() => { router.push("/account"); router.refresh(); }, 700);
    setBusy(false);
  }

  return <main className="shell"><section className="panel"><p className="eyebrow">Account security</p><h1>Choose a new password</h1><form onSubmit={submit}><label>New password<input type="password" minLength={8} required autoComplete="new-password" value={password} onChange={event => setPassword(event.target.value)} /></label><div className="actions"><button className="primary" disabled={busy || !supabase} type="submit">{busy ? "Updating…" : "Update password"}</button><Link href="/auth">Back to sign in</Link></div></form>{message && <div className="notice-card" role="status">{message}</div>}</section></main>;
}

import { isDevelopmentTurnstileBypass } from "@/lib/server/env";

const VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify";
const PREVIEW_TEST_SECRET = "1x0000000000000000000000000000000AA";

interface TurnstileResponse { success?: boolean; action?: string; hostname?: string; "error-codes"?: string[]; }
export interface ChallengeResult { ok: boolean; reason?: "missing_token" | "not_configured" | "verification_failed" | "action_mismatch"; bypassed?: boolean; }

function effectiveSecret() {
  const configured = process.env.TURNSTILE_SECRET_KEY?.trim();
  if (configured) return configured;
  return process.env.VERCEL_ENV === "preview" ? PREVIEW_TEST_SECRET : undefined;
}

export async function verifyTurnstile(token: string | undefined, expectedAction: string, fetcher: typeof fetch = fetch): Promise<ChallengeResult> {
  if (isDevelopmentTurnstileBypass() && token === "dev-bypass") return { ok: true, bypassed: true };
  const secret = effectiveSecret();
  if (!secret) return { ok: false, reason: "not_configured" };
  if (!token || token.length > 2048) return { ok: false, reason: "missing_token" };
  try {
    const response = await fetcher(VERIFY_URL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ secret, response: token }) });
    if (!response.ok) return { ok: false, reason: "verification_failed" };
    const result = await response.json() as TurnstileResponse;
    if (!result.success) return { ok: false, reason: "verification_failed" };
    if (result.action && result.action !== expectedAction) return { ok: false, reason: "action_mismatch" };
    return { ok: true };
  } catch { return { ok: false, reason: "verification_failed" }; }
}

